{"facts": [
  {"fact_id": "F1", "about": "user", "kind": "lasting", "existing": [], "adds": "yes", "new": ["User owns an amber hiking backpack."], "same_as_fact": null},
  {"fact_id": "F2", "about": "user", "kind": "lasting", "existing": [], "adds": "yes", "new": ["User owns a white canoe."], "same_as_fact": null},
  {"fact_id": "F3", "about": "user", "kind": "lasting", "existing": [], "adds": "yes", "new": ["User prefers decaf coffee."], "same_as_fact": null},
  {"fact_id": "F4", "about": "user's sister", "kind": "lasting", "existing": [], "adds": "yes", "new": ["User's sister prefers green tea."], "same_as_fact": null}
],
"deletes": []}

