  {"id": "O2", "text": "The on-call rotation is Ana, Ben, Cleo and Dev.", "mentioned_at": "2025-04-01"}
  {"id": "O3", "text": "Cleo is on call on Mondays.", "mentioned_at": "2025-04-01"}
