    "_DeleteAction": {
      "description": "One DELETE from an LLM response.\n\n``observation_id`` stays required — a delete naming no target has no defensible\nfallback, and guessing one would remove the wrong observation. But rejecting the\nentry rejects the ENTIRE ``_FactBatchResponse``, taking the batch's\nperfectly good creates and updates with it (#4152), so a near-miss is worth\nabsorbing rather than paying a bisected re-run for: models that copy the\nobservation's own field name emit ``id``, which is unambiguous here because a\ndelete entry has exactly one identifier. ``populate_by_name`` keeps the\ncanonical name working for in-process construction, and the generated JSON\nschema still advertises ``observation_id`` alone (pydantic emits the first\nof the ``AliasChoices``), so what a grammar-constrained provider is told to\nemit does not change — this only widens what a free-form one gets away with.",
      "properties": {
        "observation_id": {
          "title": "Observation Id",
          "type": "string"
        },
        "merged_into": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Merged Into"
        },
        "reason": {
          "default": "",
          "title": "Reason",
          "type": "string"
        }
      },
      "required": [
        "observation_id"
      ],
      "title": "_DeleteAction",
      "type": "object"
    },
    "_Fact": {
